using MediatR; using PartyNL.Application.Abstractions.Repositories; using PartyNL.Domain.Enums;
namespace PartyNL.Application.Features.Events.Queries.GetAllEvents;
public sealed record GetAllEventsQuery:IRequest<GetAllEventsResponse>;public sealed record EventResponse(Guid Id,Guid OrganizerId,Guid LocationId,string Title,string? Description,DateTime StartDate,DateTime EndDate,decimal Price,int Capacity,int MinimumAge,EventVisibility Visibility,EventStatus Status,string? CoverImageUrl);public sealed record GetAllEventsResponse(IEnumerable<EventResponse> Events);
public sealed class GetAllEventsHandler(IEventRepository repository):IRequestHandler<GetAllEventsQuery,GetAllEventsResponse>{public async Task<GetAllEventsResponse> Handle(GetAllEventsQuery request,CancellationToken cancellationToken){var items=await repository.GetAllAsync();return new(items.Select(e=>new EventResponse(e.Id,e.OrganizerId,e.LocationId,e.Title,e.Description,e.StartDate,e.EndDate,e.Price,e.Capacity,e.MinimumAge,e.Visibility,e.Status,e.CoverImageUrl)));}}